const aria2=(()=>{let hash=Date.now().toString(36)+"-"+Math.random().toString(36).substring(2);let index=0;let events={};let pending=new Map;let shared=document.currentScript.src.replace("worker-client.js","socket-worker.js");let worker=new SharedWorker(shared,{name:"aria2-socket-worker"});let port=worker.port;port.start();port.onmessage=event=>{let data=event.data;let id=data.id;let func=pending.get(id);if(func){pending.delete(id);func(data.result);return}let post=events[data.type];if(post){post(data.details);return}};function broadcast(type,payload){let id=hash+"-"+index+++"-"+type;return new Promise(resolve=>{pending.set(id,resolve);port.postMessage({id:id,type:type,payload:payload})})}let aria2={call(method,params){return broadcast("call",{method:method,params:params})},multicall(requests){return broadcast("multicall",requests)},connect(jsonrpc,secret){return broadcast("connect",{jsonrpc:jsonrpc,secret:secret})},disconnect(){return broadcast("disconnect")},subscribe(){return broadcast("subscribe")},unsubscribe(){return broadcast("unsubscribe")},set(key,value){return broadcast(key,value)},get(key){return broadcast(key)}};Object.defineProperty(aria2,"onopen",{get(){return events["ws:open"]},set(callback){if(typeof callback==="function"){events["ws:open"]=callback}else{events["ws:open"]=null}}});Object.defineProperty(aria2,"onclose",{get(){return events["ws:close"]},set(callback){if(typeof callback==="function"){events["ws:close"]=callback}else{events["ws:close"]=null}}});Object.defineProperty(aria2,"onmessage",{get(){return events["ws:message"]},set(callback){if(typeof callback==="function"){events["ws:message"]=callback}else{events["ws:message"]=null}}});window.addEventListener("pagehide",event=>{aria2.unsubscribe()});return aria2})();